def weighted_total(a):
    total = 0
    for i in range(len(a)):
        for j in range(3):
            total += a[i] * j
    return total

def count_steps(n):
    steps = 0
    for i in range(n):
        j = i
        while j < n:
            j += 1
            steps += 1
    return steps

def halvings(n):
    count = 0
    while n > 1:
        n //= 2
        count += 1
    return count

def build(n):
    items = []
    for i in range(n):
        items.append(i)   # dynamic array: occasionally resizes and copies
    return items
